import type { AppConfig } from './types';
import { local } from './local';
import { production } from './production';

export type { AppConfig };

/**
 * The active config, chosen by Vite mode:
 *   - `vite build` (mode `production`)  -> production
 *   - `vite` dev server, `vite build --mode development` (npm run build:local), tests -> local
 *
 * The condition is a build-time constant, so the other config is tree-shaken out and a
 * local build contains no production values.
 */
export const config: AppConfig = import.meta.env.MODE === 'production' ? production : local;
