// The page's public configuration, resolved at run time: the footer's `window.RGAI_CONFIG` if it sets a
// value, else the build's config. No Supabase import here, so a widget that only needs a URL or a key
// does not pull in supabase-js.
import { config } from '../config';

declare global {
  interface Window {
    RGAI_CONFIG?: {
      supabaseUrl?: string;
      supabaseAnonKey?: string;
      /** Where the stream overlay is served from (no trailing slash); defaults to the build's config. */
      overlayBaseUrl?: string;
      /** YouTube Data API browser key / channel handle for the Shorts carousel (default: the build's config). */
      youtubeApiKey?: string;
      youtubeChannel?: string;
    };
  }
}

/** The Supabase URL of this environment: the page's RGAI_CONFIG if it sets one, else the build's config. */
export function resolveSupabaseUrl(): string {
  return window.RGAI_CONFIG?.supabaseUrl || config.supabaseUrl;
}

/** The publishable key of this environment: the page's RGAI_CONFIG if it sets one, else the build's config. */
export function resolveSupabaseKey(): string {
  return window.RGAI_CONFIG?.supabaseAnonKey || config.supabasePublishableKey;
}

/** Where the stream overlay is served from, no trailing slash. */
export function resolveOverlayBaseUrl(): string {
  return (window.RGAI_CONFIG?.overlayBaseUrl || config.overlayBaseUrl).replace(/\/$/, '');
}

/** The Shorts carousel's YouTube key: the page's RGAI_CONFIG if it sets one, else the build's config. */
export function resolveYoutubeKey(): string {
  return window.RGAI_CONFIG?.youtubeApiKey || config.youtubeApiKey;
}

/** The channel handle the carousel shows by default. */
export function resolveYoutubeChannel(): string {
  return window.RGAI_CONFIG?.youtubeChannel || config.youtubeChannel;
}
